def transform(grid):
    n=len(grid)
    out=[row[:] for row in grid]
    for r in range(n):
        for c in range(len(grid[r])):
            if grid[r][c] != 6:
                continue
            pts=set()
            for swap in (False, True):
                rr,cc=(c,r) if swap else (r,c)
                for flipr in (False, True):
                    for flipc in (False, True):
                        R=31-rr if flipr else rr
                        C=31-cc if flipc else cc
                        if 0<=R<n and 0<=C<len(grid[r]): pts.add((R,C))
            vals={grid[R][C] for R,C in pts if grid[R][C]!=6}
            if not vals: raise ValueError((r,c,'no source'))
            if len(vals)!=1: raise ValueError((r,c,vals))
            out[r][c]=vals.pop()
    return out
